using System.Windows;using VtuberBot.Core;namespace VtuberBot.App;public partial class App:Application{VtuberApplication? a;protected override void OnStartup(StartupEventArgs e){base.OnStartup(e);try{a=new();a.Initialize();var w=new MainWindow(a);MainWindow=w;w.Show();}catch(Exception x){try{Console.Error.WriteLine("VTuberBot startup failed ("+x.GetType().Name+"): "+x.Message);}catch{}MessageBox.Show(x.Message,"VTuber Bot");Shutdown(1);}}protected override void OnExit(ExitEventArgs e){a?.Shutdown();base.OnExit(e);}}